"""Generated by testgen-agent for operation 'listProducts'.

Every test here was run against the live API and passed 3 times in a row before
being written. Review before committing: passing is not the same as correct."""

from conftest import fill, get_path  # noqa: F401


def test_first_page(client):
    # default paging
    r = client.request('GET', '/api/products')
    assert r.status_code == 200, r.text
    body = r.json()
    assert get_path(body, 'total') == 23
    assert get_path(body, 'items.length') == 5
    assert get_path(body, 'totalPages') == 5
    assert get_path(body, 'page') == 1


def test_last_partial_page(client):
    # 23 items / 5 per page leaves 3 on page 5
    r = client.request('GET', '/api/products', params={'page': 5})
    assert r.status_code == 200, r.text
    body = r.json()
    assert get_path(body, 'items.length') == 3


def test_search_is_case_insensitive(client):
    r = client.request('GET', '/api/products', params={'q': 'usb'})
    assert r.status_code == 200, r.text
    body = r.json()
    assert get_path(body, 'total') == 2


def test_page_zero_rejected(client):
    # page minimum is 1
    r = client.request('GET', '/api/products', params={'page': 0})
    assert r.status_code == 400, r.text


def test_size_above_max_rejected(client):
    r = client.request('GET', '/api/products', params={'size': 51})
    assert r.status_code == 400, r.text
